"""Legacy-compatible numeric division behavior."""

from __future__ import annotations

import math
from typing import Any


_AUDIT_DIV_ZERO = "SCRIPT_DIV0"


def _coerce_numeric(value: Any) -> float:
    """Coerce a legacy numeric operand to a float."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        if value.strip() == "":
            return 0.0
        try:
            return float(value)
        except (TypeError, ValueError, OverflowError):
            return 0.0

    try:
        return float(value)
    except OverflowError:
        try:
            return math.inf if value > 0 else -math.inf
        except Exception:
            return 0.0
    except (TypeError, ValueError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using Meridian CRM's division-by-zero semantics."""
    try:
        numerator = _coerce_numeric(a)
        denominator = _coerce_numeric(b)

        if denominator == 0.0:
            return 0.0, [_AUDIT_DIV_ZERO]

        return float(numerator / denominator), []
    except Exception:
        return 0.0, [_AUDIT_DIV_ZERO]
